/* Rounded chat input bar. Consumer positions it (margin/width).
 * Follows --control-radius (pill when Pill is on, rounded otherwise) on a single
 * line; rounds to a rect once the textarea grows. 2px border (emphasis). */
.chat-composer {
  display: flex;
  /* Single line: centre the field and the voice/send button to each other.
   * Once the textarea grows (stretched) the button drops to the bottom edge. */
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-1) var(--space-1) var(--space-1) var(--space-4);
  border: 2px solid var(--input);
  border-radius: var(--control-radius);
  background: var(--background);
  transition: border-color var(--duration-fast), border-radius var(--duration-fast);
}
/* The ring, not only a recoloured border. Every other field frame in the system
 * draws --ring-width at --ring-offset on focus; this one changed a border colour,
 * so the same keypress produced a different answer depending on whether you were
 * in the composer or in a form above it. The border keeps its accent too. */
.chat-composer:focus-within {
  border-color: var(--primary-accent);
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
}
.chat-composer[data-stretched] {
  align-items: flex-end;
  border-radius: var(--radius-rect);
}

.chat-composer-field {
  flex: 1;
  min-width: 0;
  /* Single line vertically centred to the control height; grows to max then scrolls. */
  min-height: var(--control-height);
  max-height: 12rem;
  padding-block: calc((var(--control-height) - 1em * var(--leading-normal)) / 2);
  border: none;
  background: transparent;
  color: var(--foreground);
  font-family: inherit;
  font-size: var(--font-base);
  line-height: var(--leading-normal);
  resize: none;
  overflow-y: auto;
}
.chat-composer-field:focus-visible { outline: none; }
.chat-composer-field::placeholder { color: var(--muted-foreground); }

/* Send / stop use IconButton variant="filled" tone — no local overrides needed. */

/* Decorative AI spark at the inline start (opt-in via the aiSpark prop).
 * Matches the field height so the single-line centring holds. */
.chat-composer-spark {
  display: inline-flex;
  align-items: center;
  min-height: var(--control-height);
}

/* Recording cancel — danger-tinted (the waveform conveys the live state). */
.chat-composer-voice.is-recording,
.chat-composer-voice.is-recording:hover { color: var(--destructive-emphasis); background: transparent; }

/* Voice waveform — animated bars while recording (replaces the field). */
.chat-composer-waveform {
  flex: 1;
  min-width: 0;
  min-height: var(--control-height);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-1);
}
.chat-composer-waveform span {
  width: 4px;
  border-radius: 2px;
  background: var(--muted-foreground);
  transform-origin: bottom;
  animation: composer-voice-bar 1s ease-in-out infinite;
}
.chat-composer-waveform span:nth-child(1) { height: 12px; animation-delay: 0ms; }
.chat-composer-waveform span:nth-child(2) { height: 20px; animation-delay: 90ms; }
.chat-composer-waveform span:nth-child(3) { height: 8px;  animation-delay: 180ms; }
.chat-composer-waveform span:nth-child(4) { height: 24px; animation-delay: 270ms; }
.chat-composer-waveform span:nth-child(5) { height: 16px; animation-delay: 360ms; }
.chat-composer-waveform span:nth-child(6) { height: 10px; animation-delay: 450ms; }
.chat-composer-waveform span:nth-child(7) { height: 22px; animation-delay: 540ms; }
.chat-composer-waveform span:nth-child(8) { height: 14px; animation-delay: 630ms; }
.chat-composer-waveform span:nth-child(9) { height: 18px; animation-delay: 720ms; }
.chat-composer-waveform span:nth-child(10){ height: 6px;  animation-delay: 810ms; }
@keyframes composer-voice-bar {
  0%, 100% { opacity: 0.4; transform: scaleY(0.4); }
  50%      { opacity: 1;   transform: scaleY(1); }
}

import './ChatComposer.css'
import { useLayoutEffect, useRef, useState, type FormEvent, type KeyboardEvent } from 'react'
import { useTranslation } from 'react-i18next'
import { cn } from '../lib/cn'
import { Icon } from '../Icon'
import { IconButton } from '../IconButton'
import { Tooltip } from '../Tooltip'

type Props = {
  /** Controlled value (optional — composer manages its own state otherwise). */
  value?: string
  onChange?: (next: string) => void
  /** Called with the trimmed text on submit. */
  onSend?: (text: string) => void
  /** Assistant is responding — swaps send for a stop button. */
  streaming?: boolean
  /** Called when the stop button is pressed. */
  onStop?: () => void
  placeholder?: string
  /** Decorative AI spark at the inline start — marks the bar as AI-powered. */
  aiSpark?: boolean
  className?: string
}

/* Tapping the mic starts a MOCK recording: a pulsing waveform replaces the
 * field and the mic turns danger. There is no audio pipeline behind it. */

/** Rounded chat input bar: auto-growing textarea plus voice/send. A pill on one
 *  line, rounded-rect once it grows; the mic swaps to a brand-filled send as
 *  soon as there is text. Enter sends, Shift+Enter adds a newline. The consumer
 *  positions it. 
 *
 * Copy: the placeholder is an invitation, not an instruction manual: one short
 * line naming what this assistant can be asked. It disappears the moment
 * anyone types, so nothing a reader needs may live only there.
 */
export function ChatComposer({ value, onChange, onSend, streaming, onStop, placeholder, aiSpark, className }: Props) {
  const { t } = useTranslation()
  const [inner, setInner] = useState('')
  const val = value ?? inner
  const set = (v: string) => (onChange ? onChange(v) : setInner(v))
  const fieldRef = useRef<HTMLTextAreaElement>(null)
  const [stretched, setStretched] = useState(false)
  const [recording, setRecording] = useState(false)

  /* Auto-grow: reset to measure, grow to content (CSS caps via max-height). */
  useLayoutEffect(() => {
    const ta = fieldRef.current
    if (!ta) return
    ta.style.height = 'auto'
    const oneLine = parseFloat(getComputedStyle(ta).minHeight) || 0
    setStretched(ta.scrollHeight > oneLine + 4)
    ta.style.height = `${ta.scrollHeight}px`
  }, [val])

  const submit = (e: FormEvent) => {
    e.preventDefault()
    const text = val.trim()
    if (!text) return
    onSend?.(text)
    if (value === undefined) setInner('')
  }

  const onKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      submit(e)
    }
  }

  const sendVoice = () => {
    setRecording(false)
    onSend?.(t('agent.voiceMessage', { defaultValue: 'Voice message' }))
  }

  const ph = placeholder ?? t('agent.inputPlaceholder')
  const hasText = val.trim().length > 0
  return (
    <form
      className={cn('chat-composer', className)}
      data-stretched={(stretched && !recording) || undefined}
      data-recording={recording || undefined}
      onSubmit={submit}
    >
      {aiSpark && (
        <span className="chat-composer-spark" aria-hidden="true">
          <Icon name="sparkles" size="md" />
        </span>
      )}

      {recording ? (
        <span className="chat-composer-waveform" aria-label={t('agent.listening', { defaultValue: 'Listening' })}>
          {Array.from({ length: 10 }).map((_, i) => (
            // eslint-disable-next-line @eslint-react/no-array-index-key -- static, append-only list; index is a stable key here
            <span key={i} />
          ))}
        </span>
      ) : (
        <textarea
          ref={fieldRef}
          className="chat-composer-field"
          rows={1}
          value={val}
          onChange={(e) => set(e.target.value)}
          onKeyDown={onKeyDown}
          placeholder={ph}
          aria-label={ph}
        />
      )}

      {/* eslint-disable sonarjs/no-nested-conditional -- JSX state-render (streaming|recording|has-text|idle); an early-return helper would scatter the markup */}
      {streaming ? (
        <Tooltip content={t('agent.stop', { defaultValue: 'Stop' })}>
          <IconButton
            icon="stop"
            size="md"
            variant="filled"
            tone="destructive"
            type="button"
            aria-label={t('agent.stop', { defaultValue: 'Stop' })}
            onClick={onStop}
          />
        </Tooltip>
      ) : recording ? (
        <>
          {/* Cancel the recording (discard). */}
          <Tooltip content={t('agent.cancel', { defaultValue: 'Cancel' })}>
            <IconButton
              icon="close"
              size="md"
              type="button"
              className="chat-composer-voice is-recording"
              aria-label={t('agent.cancel', { defaultValue: 'Cancel' })}
              onClick={() => setRecording(false)}
            />
          </Tooltip>
          {/* Finish + send the voice message. */}
          <Tooltip content={t('agent.send')}>
            <IconButton
              icon="send"
              size="md"
              variant="filled"
              tone="primary"
              type="button"
              aria-label={t('agent.send')}
              onClick={sendVoice}
            />
          </Tooltip>
        </>
      ) : hasText ? (
        <Tooltip content={t('agent.send')}>
          <IconButton icon="send" size="md" variant="filled" tone="primary" type="submit" aria-label={t('agent.send')} />
        </Tooltip>
      ) : (
        <Tooltip content={t('agent.voiceInput')}>
          <IconButton
            icon="mic"
            size="md"
            type="button"
            className="chat-composer-voice"
            aria-label={t('agent.voiceInput')}
            onClick={() => setRecording(true)}
          />
        </Tooltip>
      )}
      {/* eslint-enable sonarjs/no-nested-conditional */}
    </form>
  )
}
